import{_ as t}from"./chunks/console-org-audit-streams.BclTeNlc.js";import{_ as a,o as r,c as o,a3 as s}from"./chunks/framework.DhF4LrUq.js";const g=JSON.parse('{"title":"Route the SIEM audit stream and read the audit trail","description":"Route the SIEM audit stream and read the audit trail - exports to your collector or bucket, the delivery ledger, and dead-letter replay.","frontmatter":{"description":"Route the SIEM audit stream and read the audit trail - exports to your collector or bucket, the delivery ledger, and dead-letter replay."},"headers":[],"relativePath":"how-to/console/siem-streams.md","filePath":"how-to/console/siem-streams.md"}'),i={name:"how-to/console/siem-streams.md"};function n(l,e,d,c,h,p){return r(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="route-the-siem-audit-stream-and-read-the-audit-trail" tabindex="-1">Route the SIEM audit stream and read the audit trail <a class="header-anchor" href="#route-the-siem-audit-stream-and-read-the-audit-trail" aria-label="Permalink to &quot;Route the SIEM audit stream and read the audit trail&quot;">​</a></h1><p>Every consequential act in ShipperDog — every mutation, decision, and refusal — lands in an immutable audit event. The <strong>SIEM audit streams</strong> screen is where that trail leaves the platform: exports carry it to your HTTPS collector in the <code>SHIPPERDOG_JSON</code> or <code>SPLUNK_HEC</code> shape, or to a storage bucket in signed batches.</p><p><img src="'+t+'" alt="The SIEM audit streams screen"></p><p>What the audit trail records and why it is immutable is covered in <a href="/shipperdog/snapshot/concepts/security-model">the security model</a>.</p><div class="tip custom-block"><p class="custom-block-title">Who holds this screen</p><p>Organization administrators alone — the surface ships security-relevant material off-platform, so no other role sees it.</p></div><h2 id="create-an-export" tabindex="-1">Create an export <a class="header-anchor" href="#create-an-export" aria-label="Permalink to &quot;Create an export&quot;">​</a></h2><ol><li><p>Open <strong>SIEM audit streams</strong> and click <strong>New SIEM export</strong>.</p></li><li><p>Pick the <strong>Kind</strong>:</p><ul><li><strong>HTTPS collector</strong> — deliveries POST to your endpoint.</li><li><strong>Bucket</strong> — signed batch files land under your <code>gs://bucket/prefix</code>.</li></ul></li><li><p>For an HTTPS collector:</p><ul><li><strong>Format</strong> — <code>SHIPPERDOG_JSON</code> (the versioned envelope) or <code>SPLUNK_HEC</code> (Splunk&#39;s HTTP Event Collector shape).</li><li><strong>Collector URL (https://)</strong> — your endpoint.</li><li><strong>Signing secret reference (secret manager)</strong> — the HMAC key for deliveries, as a secret-manager <em>reference</em>; secret material itself never enters the configuration.</li><li>Optionally an <strong>Auth header name</strong> (for example <code>Authorization</code>) and its <strong>Auth secret reference</strong> (the header value — for example the HEC token — resolved the same way).</li></ul></li><li><p>For a bucket export: the <strong>Bucket URI</strong> and the <strong>Initial watermark</strong> — empty starts at now (forward-only); <code>1970-01-01T00:00:00Z</code> backfills the entire audit trail in bounded passes.</p></li><li><p>The <strong>Event-type filter</strong> (comma-separated audit event types, empty = ALL) narrows the stream — for example only <code>AUTHORIZATION_DECISION</code>, <code>ABAC_POLICY_DENIED</code>, and their families for a pure access-governance feed.</p></li><li><p>Save. The <strong>Enabled</strong> switch parks an export without deleting it (a parked chip marks it in the list).</p></li></ol><h2 id="test-the-pipeline" tabindex="-1">Test the pipeline <a class="header-anchor" href="#test-the-pipeline" aria-label="Permalink to &quot;Test the pipeline&quot;">​</a></h2><p><strong>Test</strong> on an export pushes one synthetic envelope through the <em>real</em> delivery pipeline and answers synchronously. A green test means the collector, the signature, and the auth header all worked; a red test means the ledger below now carries the diagnostic.</p><h2 id="read-the-delivery-ledger" tabindex="-1">Read the delivery ledger <a class="header-anchor" href="#read-the-delivery-ledger" aria-label="Permalink to &quot;Read the delivery ledger&quot;">​</a></h2><p><strong>Deliveries</strong> on an export opens the ledger: every attempt with its status — <code>SCHEDULED</code> buffering, <code>DELIVERED</code> history, and the <code>FAILED</code> dead-letter. Failed deliveries retry with backoff; when exhausted they stay visible.</p><p><strong>Replay dead-letter</strong> returns every terminally failed delivery to the retry schedule with a fresh attempt budget — after you fix the collector, one click re-runs the queue.</p><h2 id="bucket-batches" tabindex="-1">Bucket batches <a class="header-anchor" href="#bucket-batches" aria-label="Permalink to &quot;Bucket batches&quot;">​</a></h2><p><strong>Batches</strong> on a bucket export lists its batch history — each batch a signed manifest of the events it carries, with the completeness rollup answering &quot;did anything get lost?&quot; Your compliance team verifies a batch against its manifest signature; nothing about the export requires trusting the platform&#39;s word for it.</p><h2 id="what-flows" tabindex="-1">What flows <a class="header-anchor" href="#what-flows" aria-label="Permalink to &quot;What flows&quot;">​</a></h2><p>The envelope is a versioned public contract — <code>event_id</code> (the dedup key), <code>event_type</code> from the frozen vocabulary, timestamps, actor, subject ids, <code>result</code>, correlation id, and the structured before/after detail. Members are append-only within a schema version; your parser will not wake up one morning to a different shape. Every type of audited act is available to the filter — governance (role changes, policy writes), the release path&#39;s every crossing, and the authorization-decision and ABAC-denial families.</p><p><strong>Related guides:</strong> <a href="/shipperdog/snapshot/how-to/console/abac-policies">ABAC policies</a> · <a href="/shipperdog/snapshot/how-to/console/sso-oidc-saml">SSO setup</a> · <a href="/shipperdog/snapshot/concepts/security-model">security model concepts</a></p>',17)])])}const f=a(i,[["render",n]]);export{g as __pageData,f as default};
